-- Loads the sample water utility star schema into Unity Catalog. Generated by generate_star.py.
-- 1. Create the schema and a volume, then upload the CSV files to it (Catalog Explorer → the volume → Upload):
--      CREATE SCHEMA IF NOT EXISTS workspace.water_star;
--      CREATE VOLUME IF NOT EXISTS workspace.water_star.raw;
-- 2. Run this in the SQL editor. It uses the workspace catalog (Databricks Free Edition and newer workspaces);
--    if yours is main or another catalog, replace workspace.water_star and /Volumes/workspace/ throughout.
-- Primary and foreign keys are informational in Unity Catalog: they document the star and drive the ERD.
-- Safe to re-run: facts are dropped before the dimensions they reference.

DROP TABLE IF EXISTS workspace.water_star.fact_water_quality;
DROP TABLE IF EXISTS workspace.water_star.fact_work_order;
DROP TABLE IF EXISTS workspace.water_star.fact_meter_read;
DROP TABLE IF EXISTS workspace.water_star.dim_wq_parameter;
DROP TABLE IF EXISTS workspace.water_star.dim_work_type;
DROP TABLE IF EXISTS workspace.water_star.dim_asset;
DROP TABLE IF EXISTS workspace.water_star.dim_site;
DROP TABLE IF EXISTS workspace.water_star.dim_tariff;
DROP TABLE IF EXISTS workspace.water_star.dim_meter;
DROP TABLE IF EXISTS workspace.water_star.dim_customer;
DROP TABLE IF EXISTS workspace.water_star.dim_date;

CREATE OR REPLACE TABLE workspace.water_star.dim_date (
  date_sk INT NOT NULL COMMENT 'Smart key yyyymmdd; -1 is unknown',
  full_date DATE NOT NULL,
  year INT NOT NULL,
  quarter INT NOT NULL,
  month INT NOT NULL,
  month_name STRING NOT NULL,
  day_of_month INT NOT NULL,
  day_of_week INT NOT NULL COMMENT '1 = Monday',
  day_name STRING NOT NULL,
  is_weekend BOOLEAN NOT NULL,
  financial_year STRING NOT NULL COMMENT 'Australian financial year, July to June, e.g. FY2024',
  season STRING NOT NULL COMMENT 'Southern hemisphere season',
  CONSTRAINT pk_dim_date PRIMARY KEY (date_sk)
) COMMENT 'Date dimension: one row per calendar day, smart key yyyymmdd';
INSERT INTO workspace.water_star.dim_date
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/DIM_DATE.csv',
  format => 'csv', header => true, schema => 'date_sk INT, full_date DATE, year INT, quarter INT, month INT, month_name STRING, day_of_month INT, day_of_week INT, day_name STRING, is_weekend BOOLEAN, financial_year STRING, season STRING');

CREATE OR REPLACE TABLE workspace.water_star.dim_customer (
  customer_sk BIGINT NOT NULL COMMENT 'Surrogate key; -1 is unknown',
  customer_id STRING NOT NULL COMMENT 'Business key: CRM customer_id',
  account_no STRING NOT NULL,
  customer_type STRING NOT NULL,
  customer_name STRING NOT NULL,
  suburb STRING NOT NULL,
  postcode STRING NOT NULL,
  concession_type STRING NOT NULL,
  segment STRING NOT NULL,
  effective_from DATE NOT NULL,
  effective_to DATE COMMENT 'NULL while current',
  is_current BOOLEAN NOT NULL,
  CONSTRAINT pk_dim_customer PRIMARY KEY (customer_sk)
) COMMENT 'Customer dimension, SCD type 2: a new version when the customer moves or their concession changes';
INSERT INTO workspace.water_star.dim_customer
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/DIM_CUSTOMER.csv',
  format => 'csv', header => true, schema => 'customer_sk BIGINT, customer_id STRING, account_no STRING, customer_type STRING, customer_name STRING, suburb STRING, postcode STRING, concession_type STRING, segment STRING, effective_from DATE, effective_to DATE, is_current BOOLEAN');

CREATE OR REPLACE TABLE workspace.water_star.dim_meter (
  meter_sk BIGINT NOT NULL COMMENT 'Surrogate key; -1 is unknown',
  meter_no STRING NOT NULL COMMENT 'Business key: meter serial number',
  meter_size_mm INT NOT NULL,
  meter_type STRING NOT NULL,
  manufacturer STRING NOT NULL,
  install_date DATE,
  CONSTRAINT pk_dim_meter PRIMARY KEY (meter_sk)
) COMMENT 'Water meter dimension (SCD type 1)';
INSERT INTO workspace.water_star.dim_meter
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/DIM_METER.csv',
  format => 'csv', header => true, schema => 'meter_sk BIGINT, meter_no STRING, meter_size_mm INT, meter_type STRING, manufacturer STRING, install_date DATE');

CREATE OR REPLACE TABLE workspace.water_star.dim_tariff (
  tariff_sk BIGINT NOT NULL COMMENT 'Surrogate key; -1 is unknown',
  tariff_code STRING NOT NULL COMMENT 'Business key',
  tariff_name STRING NOT NULL,
  customer_type STRING NOT NULL,
  tier1_rate_per_kl DECIMAL(8,4) NOT NULL,
  tier1_limit_kl_per_day DECIMAL(6,3) NOT NULL,
  tier2_rate_per_kl DECIMAL(8,4) NOT NULL,
  supply_charge_per_quarter DECIMAL(8,2) NOT NULL,
  CONSTRAINT pk_dim_tariff PRIMARY KEY (tariff_sk)
) COMMENT 'Water tariff dimension (SCD type 1); rates are fictional';
INSERT INTO workspace.water_star.dim_tariff
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/DIM_TARIFF.csv',
  format => 'csv', header => true, schema => 'tariff_sk BIGINT, tariff_code STRING, tariff_name STRING, customer_type STRING, tier1_rate_per_kl DECIMAL(8,4), tier1_limit_kl_per_day DECIMAL(6,3), tier2_rate_per_kl DECIMAL(8,4), supply_charge_per_quarter DECIMAL(8,2)');

CREATE OR REPLACE TABLE workspace.water_star.dim_site (
  site_sk BIGINT NOT NULL COMMENT 'Surrogate key; -1 is unknown',
  site_code STRING NOT NULL COMMENT 'Business key: matches LOCATIONS.LOCATION',
  site_name STRING NOT NULL,
  site_type STRING NOT NULL,
  region STRING NOT NULL,
  is_drinking_water BOOLEAN NOT NULL,
  CONSTRAINT pk_dim_site PRIMARY KEY (site_sk)
) COMMENT 'Operational site dimension: treatment plants, pump stations, reservoirs';
INSERT INTO workspace.water_star.dim_site
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/DIM_SITE.csv',
  format => 'csv', header => true, schema => 'site_sk BIGINT, site_code STRING, site_name STRING, site_type STRING, region STRING, is_drinking_water BOOLEAN');

CREATE OR REPLACE TABLE workspace.water_star.dim_asset (
  asset_sk BIGINT NOT NULL COMMENT 'Surrogate key; -1 is unknown',
  asset_tag STRING NOT NULL COMMENT 'Business key: matches ASSET_GOLDEN.asset_tag',
  asset_name STRING NOT NULL,
  asset_class STRING NOT NULL,
  system_name STRING NOT NULL,
  facility_name STRING NOT NULL,
  manufacturer STRING,
  criticality INT,
  install_date DATE,
  CONSTRAINT pk_dim_asset PRIMARY KEY (asset_sk)
) COMMENT 'Maintainable equipment dimension (SCD type 1), flattened with its system and facility';
INSERT INTO workspace.water_star.dim_asset
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/DIM_ASSET.csv',
  format => 'csv', header => true, schema => 'asset_sk BIGINT, asset_tag STRING, asset_name STRING, asset_class STRING, system_name STRING, facility_name STRING, manufacturer STRING, criticality INT, install_date DATE');

CREATE OR REPLACE TABLE workspace.water_star.dim_work_type (
  work_type_sk BIGINT NOT NULL COMMENT 'Surrogate key; -1 is unknown',
  work_type_code STRING NOT NULL COMMENT 'Business key',
  work_type_name STRING NOT NULL,
  is_planned BOOLEAN NOT NULL,
  CONSTRAINT pk_dim_work_type PRIMARY KEY (work_type_sk)
) COMMENT 'Maintenance work type dimension';
INSERT INTO workspace.water_star.dim_work_type
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/DIM_WORK_TYPE.csv',
  format => 'csv', header => true, schema => 'work_type_sk BIGINT, work_type_code STRING, work_type_name STRING, is_planned BOOLEAN');

CREATE OR REPLACE TABLE workspace.water_star.dim_wq_parameter (
  parameter_sk BIGINT NOT NULL COMMENT 'Surrogate key; -1 is unknown',
  parameter_code STRING NOT NULL COMMENT 'Business key',
  parameter_name STRING NOT NULL,
  unit STRING NOT NULL,
  guideline_min DECIMAL(10,3),
  guideline_max DECIMAL(10,3),
  CONSTRAINT pk_dim_wq_parameter PRIMARY KEY (parameter_sk)
) COMMENT 'Drinking water quality parameter dimension; limits are illustrative';
INSERT INTO workspace.water_star.dim_wq_parameter
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/DIM_WQ_PARAMETER.csv',
  format => 'csv', header => true, schema => 'parameter_sk BIGINT, parameter_code STRING, parameter_name STRING, unit STRING, guideline_min DECIMAL(10,3), guideline_max DECIMAL(10,3)');

CREATE OR REPLACE TABLE workspace.water_star.fact_meter_read (
  read_date_sk INT NOT NULL,
  customer_sk BIGINT NOT NULL COMMENT 'The customer version in force on the read date',
  meter_sk BIGINT NOT NULL,
  tariff_sk BIGINT NOT NULL,
  read_no STRING NOT NULL COMMENT 'Degenerate dimension: billing read number',
  read_type STRING NOT NULL COMMENT 'ACTUAL or ESTIMATED',
  days_in_period INT NOT NULL,
  consumption_kl DECIMAL(10,2) NOT NULL,
  usage_charge DECIMAL(12,2) NOT NULL,
  supply_charge DECIMAL(12,2) NOT NULL
) COMMENT 'Billing consumption. Grain: one row per meter read (a customer''s quarterly reading of one meter)';
INSERT INTO workspace.water_star.fact_meter_read
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/FACT_METER_READ.csv',
  format => 'csv', header => true, schema => 'read_date_sk INT, customer_sk BIGINT, meter_sk BIGINT, tariff_sk BIGINT, read_no STRING, read_type STRING, days_in_period INT, consumption_kl DECIMAL(10,2), usage_charge DECIMAL(12,2), supply_charge DECIMAL(12,2)');

CREATE OR REPLACE TABLE workspace.water_star.fact_work_order (
  raised_date_sk INT NOT NULL,
  completed_date_sk INT NOT NULL,
  asset_sk BIGINT NOT NULL,
  site_sk BIGINT NOT NULL,
  work_type_sk BIGINT NOT NULL,
  work_order_no STRING NOT NULL COMMENT 'Degenerate dimension',
  labour_hours DECIMAL(8,2) NOT NULL,
  labour_cost DECIMAL(12,2) NOT NULL,
  material_cost DECIMAL(12,2) NOT NULL,
  downtime_hours DECIMAL(8,2) NOT NULL
) COMMENT 'Maintenance. Grain: one row per completed work order';
INSERT INTO workspace.water_star.fact_work_order
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/FACT_WORK_ORDER.csv',
  format => 'csv', header => true, schema => 'raised_date_sk INT, completed_date_sk INT, asset_sk BIGINT, site_sk BIGINT, work_type_sk BIGINT, work_order_no STRING, labour_hours DECIMAL(8,2), labour_cost DECIMAL(12,2), material_cost DECIMAL(12,2), downtime_hours DECIMAL(8,2)');

CREATE OR REPLACE TABLE workspace.water_star.fact_water_quality (
  sample_date_sk INT NOT NULL,
  site_sk BIGINT NOT NULL,
  parameter_sk BIGINT NOT NULL,
  sample_no STRING NOT NULL COMMENT 'Degenerate dimension: lab sample number',
  result_value DECIMAL(10,3) NOT NULL,
  exceedance_count INT NOT NULL COMMENT '1 when outside the guideline, else 0, so it sums'
) COMMENT 'Drinking water quality. Grain: one row per lab result (one parameter of one sample)';
INSERT INTO workspace.water_star.fact_water_quality
SELECT * FROM read_files('/Volumes/workspace/water_star/raw/FACT_WATER_QUALITY.csv',
  format => 'csv', header => true, schema => 'sample_date_sk INT, site_sk BIGINT, parameter_sk BIGINT, sample_no STRING, result_value DECIMAL(10,3), exceedance_count INT');

ALTER TABLE workspace.water_star.fact_meter_read ADD CONSTRAINT fk_fact_meter_read_read_date_sk FOREIGN KEY (read_date_sk) REFERENCES workspace.water_star.dim_date (date_sk);
ALTER TABLE workspace.water_star.fact_meter_read ADD CONSTRAINT fk_fact_meter_read_customer_sk FOREIGN KEY (customer_sk) REFERENCES workspace.water_star.dim_customer (customer_sk);
ALTER TABLE workspace.water_star.fact_meter_read ADD CONSTRAINT fk_fact_meter_read_meter_sk FOREIGN KEY (meter_sk) REFERENCES workspace.water_star.dim_meter (meter_sk);
ALTER TABLE workspace.water_star.fact_meter_read ADD CONSTRAINT fk_fact_meter_read_tariff_sk FOREIGN KEY (tariff_sk) REFERENCES workspace.water_star.dim_tariff (tariff_sk);
ALTER TABLE workspace.water_star.fact_work_order ADD CONSTRAINT fk_fact_work_order_raised_date_sk FOREIGN KEY (raised_date_sk) REFERENCES workspace.water_star.dim_date (date_sk);
ALTER TABLE workspace.water_star.fact_work_order ADD CONSTRAINT fk_fact_work_order_completed_date_sk FOREIGN KEY (completed_date_sk) REFERENCES workspace.water_star.dim_date (date_sk);
ALTER TABLE workspace.water_star.fact_work_order ADD CONSTRAINT fk_fact_work_order_asset_sk FOREIGN KEY (asset_sk) REFERENCES workspace.water_star.dim_asset (asset_sk);
ALTER TABLE workspace.water_star.fact_work_order ADD CONSTRAINT fk_fact_work_order_site_sk FOREIGN KEY (site_sk) REFERENCES workspace.water_star.dim_site (site_sk);
ALTER TABLE workspace.water_star.fact_work_order ADD CONSTRAINT fk_fact_work_order_work_type_sk FOREIGN KEY (work_type_sk) REFERENCES workspace.water_star.dim_work_type (work_type_sk);
ALTER TABLE workspace.water_star.fact_water_quality ADD CONSTRAINT fk_fact_water_quality_sample_date_sk FOREIGN KEY (sample_date_sk) REFERENCES workspace.water_star.dim_date (date_sk);
ALTER TABLE workspace.water_star.fact_water_quality ADD CONSTRAINT fk_fact_water_quality_site_sk FOREIGN KEY (site_sk) REFERENCES workspace.water_star.dim_site (site_sk);
ALTER TABLE workspace.water_star.fact_water_quality ADD CONSTRAINT fk_fact_water_quality_parameter_sk FOREIGN KEY (parameter_sk) REFERENCES workspace.water_star.dim_wq_parameter (parameter_sk);
